using DSAExperimentation.DataStructures.Graph.Engines.Dags.Trees; using NodeStack = DSAExperimentation.DataStructures.Stack.Stack<DSAExperimentation.DataStructures.Graph.Engines.Dags.Trees.BinaryTreeNode<int>>;
namespace DSAExperimentation.Tests.LeetCodeCoverage.BinarySearchTreeIterator;
public sealed partial class BinarySearchTreeIteratorTests { [Fact] public void BstIterator_Example_ReturnsInOrder(){var it=new BstIterator(new BinaryTreeNode<int>(7){Left=new(3),Right=new(15){Left=new(9),Right=new(20)}});Assert.Equal(3,it.Next());Assert.Equal(7,it.Next());Assert.True(it.HasNext());Assert.Equal(9,it.Next());} private sealed class BstIterator{private readonly NodeStack _stack=new();public BstIterator(BinaryTreeNode<int>? root)=>PushLeft(root);public bool HasNext()=>_stack.Count>0;public int Next(){_stack.TryPop(out var n);PushLeft(n.Right);return n.Value;}private void PushLeft(BinaryTreeNode<int>? n){while(n is not null){_stack.Push(n);n=n.Left;}}} }
